import unittest
from candidate import flip_case

class TestFlipCase(unittest.TestCase):
    def test_normal_lowercase_input(self):
        self.assertEqual(flip_case('hello'), 'HELLO')

    def test_normal_uppercase_input(self):
        self.assertEqual(flip_case('HELLO'), 'hello')

    def test_mixed_case_input(self):
        self.assertEqual(flip_case('HeLLo WoRLd'), 'hELLO wORLD')

    def test_empty_string(self):
        self.assertEqual(flip_case(''), '')

    def test_single_character_lower(self):
        self.assertEqual(flip_case('a'), 'A')

    def test_single_character_upper(self):
        self.assertEqual(flip_case('A'), 'a')

    def test_numeric_string(self):
        self.assertEqual(flip_case('123'), '123')

    def test_special_characters(self):
        self.assertEqual(flip_case('!@#'), '!@#')

    def test_unicode_lowercase(self):
        self.assertEqual(flip_case('café'), 'CAFÉ')

    def test_unicode_uppercase(self):
        self.assertEqual(flip_case('Café'), 'café')

    def test_none_input(self):
        with self.assertRaises(TypeError):
            flip_case(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            flip_case(123)

    def test_case_mixed_with_special_chars(self):
        self.assertEqual(flip_case('H3ll0 W0rld!'), 'h3LL0 w0RLD!')

    def test_all_special_chars(self):
        self.assertEqual(flip_case('!@#$%^&*()'), '!@#$%^&*()')
